import{_ as a,c as i,o as t,a2 as r}from"./chunks/framework.bjzS3PU6.js";const u=JSON.parse('{"title":"G*BOY","description":"","frontmatter":{},"headers":[],"relativePath":"entries/subjects/G-BOY.md","filePath":"entries/subjects/G-BOY.md"}'),o={name:"entries/subjects/G-BOY.md"};function n(s,e,l,c,h,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="g-boy" tabindex="-1">G*BOY <a class="header-anchor" href="#g-boy" aria-label="Permalink to &quot;G*BOY&quot;">​</a></h1><hr><p><strong>DESIGNATION</strong>: Subject G-304<br><strong>FACILITY</strong>: <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a><br><strong>CLASSIFICATION</strong>: Tier-0 Prototype (alleged)<br><strong>STATUS</strong>: Escaped (early 2000s)</p><hr><p><strong>G*BOY</strong> (officially designated <strong>Subject G-304</strong>) is a former research subject who escaped from the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> in the early 2000s. The escape, which resulted in a facility-wide security failure, drew widespread attention and made G*BOY a symbolic figure for The Bloc, an activist organization investigating alleged corporate research misconduct.</p><p><strong>At a glance</strong></p><ul><li>Former research subject (Designation: G-304) at Saint Juniper Research Campus</li><li>Possesses consciousness transfer ability known as &quot;head jack&quot;</li><li>Escaped containment in early 2000s during major facility incident</li><li>Appeared in <a href="./../locations/Shinkai-Metropolis">Shinkai Metropolis</a> mind place following dimensional incident</li><li>Subject of unsuccessful recovery operations led by Nocturne Squadron</li><li>Adopted as symbol by The Bloc activist movement</li><li>Distinctive appearance: red hooded figure with horns</li><li>Current whereabouts unknown (believed to be in the Mindverse)</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Subject G-304 was held at the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> as part of what The Bloc alleges to be unauthorized research programs conducted by the <a href="./../organizations/Miter-Corporation">Miter Corporation</a>. The subject&#39;s escape in the early 2000s resulted in a major facility security breach and triggered recovery operations that, according to facility administrators, proved unsuccessful.</p><p>The subject became widely known following The Bloc&#39;s public awareness campaign, which adopted the red-hooded figure as a symbol of resistance against alleged corporate misconduct. The distinctive appearance and circumstances of the escape contributed to G*BOY becoming a cultural icon within activist communities.</p><h2 id="background-and-containment" tabindex="-1">Background and containment <a class="header-anchor" href="#background-and-containment" aria-label="Permalink to &quot;Background and containment&quot;">​</a></h2><p>Little verified information is publicly available about G-304&#39;s time at the facility. According to claims by The Bloc, the subject was held in a specialized containment area designated Chamber 304 and subjected to experimental procedures. The Bloc alleges that G-304 was part of classified research programs involving what they term &quot;gravitational cognition&quot; experiments, though these claims have not been independently verified.</p><p>The facility has not released official statements regarding the nature of research conducted with G-304 or the circumstances of the subject&#39;s initial intake.</p><h2 id="the-escape" tabindex="-1">The escape <a class="header-anchor" href="#the-escape" aria-label="Permalink to &quot;The escape&quot;">​</a></h2><p>In the early 2000s, G-304 escaped from the Saint Juniper Research Campus in an incident that resulted in significant facility damage and a facility-wide power failure. The Bloc obtained and circulated security footage showing the escape, which depicted extensive structural damage and what appeared to be unusual environmental conditions during the breach.</p><p>Following the escape, facility administrator Dr. Ravel announced that G-304 had been located and that recovery operations led by Agent K and Nocturne Squadron were underway. However, this broadcast was interrupted by <a href="./../people/Z-L1NE">Z*L1NE</a> of The Bloc, who delivered a counter-message to facility personnel. G-304&#39;s whereabouts remain unknown, and no official confirmation of recapture has been issued.</p><h2 id="cultural-impact" tabindex="-1">Cultural impact <a class="header-anchor" href="#cultural-impact" aria-label="Permalink to &quot;Cultural impact&quot;">​</a></h2><p>Following the escape, The Bloc launched a public awareness campaign that adopted G<em>BOY&#39;s distinctive red-hooded appearance as a symbol of resistance. The imagery spread through activist communities in Saint Juniper and beyond, appearing in street art, clothing, and protest materials. The campaign positioned G</em>BOY as a symbol of liberation from alleged corporate experimentation.</p><p>The visual iconography proved effective at raising awareness of The Bloc&#39;s allegations regarding Miter Corporation research practices. G*BOY became the organization&#39;s most recognizable symbol and a rallying point for supporters of their investigative efforts.</p><h3 id="media-coverage-and-public-perception" tabindex="-1">Media Coverage and Public Perception <a class="header-anchor" href="#media-coverage-and-public-perception" aria-label="Permalink to &quot;Media Coverage and Public Perception&quot;">​</a></h3><p>G<em>BOY has received significant media attention across multiple platforms. Conspiracy theorist <a href="./../people/Conspirazorg">Conspirazorg</a> discussed G</em>BOY&#39;s escape on <a href="./../organizations/SnarkCast">SnarkCast</a> in November 2025, identifying G*BOY as an escaped facility subject who had &quot;blown up online&quot; and become &quot;some sort of symbol.&quot;</p><p>In late November 2025, <em>SnarkCast</em> host <a href="./../people/Milton-Plumb">Milton Plumb</a> and guest <a href="./../people/Rectford-Shillman">Rectford Shillman</a> characterized G<em>BOY as a &quot;terrorist,&quot; warning about <a href="./../organizations/The-Bloc">The Bloc</a>&#39;s planned blockchain activities involving the G</em>BOY symbol.</p><p>In December 2025, The Bloc launched the $GBOY cryptocurrency token, which was subsequently analyzed on the financial program <a href="./../organizations/Market-Talk">Market Talk</a>. Anchor <a href="./../people/Denise-Kepler">Denise Kepler</a> described the project as &quot;just a memecoin from a group of people posting pictures of a red-hooded boy trying to make some sort of change,&quot; dismissing it as not worthy of sustained coverage. Analysts <a href="./../people/Cynthia-Milkins">Cynthia Milkins</a> and <a href="./../people/Bradleigh-Font">Bradleigh Font</a> reported on the token&#39;s volatile price movements and widespread grassroots marketing, including G*BOY stickers appearing on personal property.</p><h2 id="abilities-and-the-mindverse" tabindex="-1">Abilities and the Mindverse <a class="header-anchor" href="#abilities-and-the-mindverse" aria-label="Permalink to &quot;Abilities and the Mindverse&quot;">​</a></h2><p>According to recovered accounts, G-304 developed or possessed an unusual ability during time at the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>—a consciousness transfer capability referred to as &quot;head jack.&quot; This ability reportedly allowed G-304 to transfer consciousness into another person&#39;s mind and control their body.</p><p>Further reports describe G-304&#39;s discovery that human minds contain what are termed &quot;mind places&quot;—internal mental realms constructed from memories and imagination. These mind places are allegedly interconnected through a network called the Mindverse, which includes both individual mental realms and independent shared spaces.</p><p>Following escape from the facility, G-304 reportedly appeared in <a href="./../locations/Shinkai-Metropolis">Shinkai Metropolis</a>, a mind place within this network. The appearance was attributed to &quot;a tear in the realities&quot; caused by what sources describe as &quot;a ritual accident&quot;—possibly connected to <a href="./../organizations/The-Bloc">The Bloc</a>&#39;s activities. G-304 and a companion named <a href="./BLOWPIE">BLOWPIE</a> were detained as &quot;anomalies&quot; by local authorities but escaped by commandeering a vessel.</p><p>These accounts suggest G-304 may currently exist within the Mindverse network rather than physical space, which could explain the failure of recovery operations.</p><h2 id="historical-claims" tabindex="-1">Historical claims <a class="header-anchor" href="#historical-claims" aria-label="Permalink to &quot;Historical claims&quot;">​</a></h2><p><a href="./../people/Magdalena">Magdalena</a>, operator of the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> and early supporter of The Bloc, has claimed that figures resembling G<em>BOY appear in historical artifacts and ancient texts in her collection. She reports possessing a statue that allegedly predates modern records of G-304&#39;s existence. These claims remain unverified by independent scholars, though they have contributed to G</em>BOY&#39;s mythological status within activist and paranormal research communities.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./BLOWPIE">BLOWPIE</a> — Companion who travels with G*BOY through the Mindverse</li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> — Research facility</li><li><a href="./../concepts/The-Mindverse">The Mindverse</a> — Network of mental realms G*BOY discovered and navigates</li><li><a href="./../locations/Shinkai-Metropolis">Shinkai Metropolis</a> — Mind place where G*BOY appeared as anomaly</li><li><a href="./../organizations/The-Bloc">The Bloc</a> — Activist organization that adopted G*BOY as symbol</li><li><a href="./../people/Z-L1NE">Z*L1NE</a> — Bloc co-founder, broadcast hijacker</li><li><a href="./../people/Magdalena">Magdalena</a> — Occult researcher with historical G*BOY artifacts</li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> — Location of ancient statue resembling G*BOY</li><li><a href="./../organizations/Miter-Corporation">Miter Corporation</a> — Alleged facility operator</li><li><a href="./../organizations/Aurelian-Systems">Aurelian Systems</a> — Research partner analyzing G-304 modulation trials</li><li><a href="./../organizations/SnarkCast">SnarkCast</a> — Satirical podcast covering G*BOY conspiracy theories</li><li><a href="./../organizations/Market-Talk">Market Talk</a> — Financial program analyzing $GBOY cryptocurrency</li><li><a href="./../people/Conspirazorg">Conspirazorg</a> — Conspiracy theorist discussing G*BOY escape</li><li><a href="./../people/Milton-Plumb">Milton Plumb</a> — SnarkCast host who characterized G*BOY as terrorist</li><li><a href="./../people/Denise-Kepler">Denise Kepler</a> — Market Talk anchor covering $GBOY token</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Regional news coverage of Saint Juniper Research Campus security breach (early 2000s)</li><li>Security footage released by The Bloc showing facility escape</li><li>Dr. Ravel public broadcast regarding recovery operations</li><li>The Bloc public awareness campaign materials</li><li>&quot;G*BOY: Symbol of Resistance or Dangerous Fugitive?&quot; investigative reporting</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',36)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
